/**
 * Proxy API Service
 * 
 * This service provides an endpoint to fetch data from external URLs.
 * It includes security measures against Server-Side Request Forgery (SSRF),
 * input validation, and resource exhaustion protection.
 */

const express = require('express');
const axios = require('axios');
const dns = require('dns').promises;
const { isIP } = require('net');
const validator = require('validator');

const app = express();
app.use(express.json());

// Configuration
const PORT = process.env.PORT || 3000;
const REQUEST_TIMEOUT_MS = 5000; // 5 seconds
const MAX_CONTENT_SIZE_BYTES = 1024 * 1024 * 2; // 2MB limit

/**
 * Validates if an IP address is private or reserved (SSRF Protection).
 * @param {string} ip 
 * @returns {boolean}
 */
const isPrivateIP = (ip) => {
    // Check for IPv4 private ranges
    const parts = ip.split('.').map(Number);
    if (parts[0] === 10 || 
        (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) || 
        (parts[0] === 192 && parts[1] === 168) ||
        (parts[0] === 127) ||
        (parts[0] === 169 && parts[1] === 254) ||
        (parts[0] === 0)) {
        return true;
    }
    // Check for IPv6 loopback/private
    if (ip === '::1' || ip.startsWith('fe80') || ip.startsWith('fc00')) {
        return true;
    }
    return false;
};

/**
 * Validates the URL and resolves the hostname to check for SSRF.
 * @param {string} urlString 
 * @returns {Promise<string>} Validated URL
 */
const validateAndResolveUrl = async (urlString) => {
    if (!validator.isURL(urlString, { protocols: ['http', 'https'], require_protocol: true })) {
        throw new Error('Invalid URL format. Only HTTP and HTTPS are supported.');
    }

    const parsedUrl = new URL(urlString);
    const hostname = parsedUrl.hostname;

    // Resolve hostname to IP to prevent DNS rebinding and access to internal network
    try {
        const lookup = await dns.lookup(hostname);
        if (isPrivateIP(lookup.address)) {
            throw new Error('Access to internal or private network addresses is prohibited.');
        }
    } catch (err) {
        if (err.code === 'ENOTFOUND') throw new Error('Could not resolve host.');
        throw err;
    }

    return urlString;
};

/**
 * POST /fetch
 * Body: { "url": "https://example.com" }
 */
app.post('/fetch', async (req, res) => {
    const { url } = req.body;

    if (!url) {
        return res.status(400).json({ error: 'URL parameter is required.' });
    }

    try {
        // 1. Security Validation (SSRF & Protocol)
        const safeUrl = await validateAndResolveUrl(url);

        // 2. Perform Request
        const response = await axios({
            method: 'get',
            url: safeUrl,
            timeout: REQUEST_TIMEOUT_MS,
            maxContentLength: MAX_CONTENT_SIZE_BYTES,
            // Prevent following redirects to avoid SSRF bypass via redirect to internal IP
            maxRedirects: 5, 
            headers: {
                'User-Agent': 'ProxyService/1.0.0',
                'Accept': 'application/json, text/plain, */*'
            },
            // Ensure we don't crash on non-2xx status codes, we want to return them
            validateStatus: () => true 
        });

        // 3. Return Response
        // We only return specific headers to avoid leaking upstream server info
        const allowedHeaders = ['content-type', 'last-modified', 'etag'];
        const responseHeaders = {};
        allowedHeaders.forEach(h => {
            if (response.headers[h]) responseHeaders[h] = response.headers[h];
        });

        res.set(responseHeaders);
        return res.status(response.status).send(response.data);

    } catch (error) {
        // 4. Error Handling
        if (error.code === 'ECONNABORTED') {
            return res.status(504).json({ error: 'Request timed out.' });
        }

        if (error.message.includes('maxContentLength')) {
            return res.status(413).json({ error: 'Response payload too large.' });
        }

        return res.status(400).json({ 
            error: 'Failed to fetch data.', 
            details: error.message 
        });
    }
});

// Global Error Handler
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(PORT, () => {
    console.log(`Proxy API running on port ${PORT}`);
});
